export type Categoria = 'Comida' | 'Transporte' | 'Servicios' | 'Ocio' | 'Salud' | 'Otros'

export interface Movimiento {
  fecha: string // AAAA-MM-DD
  descripcion: string
  monto: number // positivo = gasto, en pesos
  categoria: Categoria
}

export function validarMovimiento(m: Movimiento): string[] {
  const errores: string[] = []
  if (!/^\d{4}-\d{2}-\d{2}$/.test(m.fecha)) errores.push('fecha inválida')
  if (m.descripcion.trim() === '') errores.push('descripción vacía')
  if (!Number.isFinite(m.monto) || m.monto <= 0) errores.push('monto inválido')
  return errores
}

export function delMes(movs: Movimiento[], mes: string): Movimiento[] {
  return movs.filter((m) => m.fecha.startsWith(`${mes}-`))
}
import { mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs'
import { dirname } from 'node:path'
import type { Movimiento } from './movimientos.js'

export function leer(ruta: string): Movimiento[] {
  if (!existsSync(ruta)) return []
  return JSON.parse(readFileSync(ruta, 'utf8')) as Movimiento[]
}

export function guardar(ruta: string, movs: Movimiento[]): void {
  mkdirSync(dirname(ruta), { recursive: true })
  writeFileSync(ruta, JSON.stringify(movs, null, 2))
}
#!/usr/bin/env node
import { leer, guardar } from './almacen.js'
import { validarMovimiento, delMes, type Categoria } from './movimientos.js'

const RUTA = process.env.FINANZAS_DATOS ?? 'data/movimientos.json'
const [comando, ...args] = process.argv.slice(2)

if (comando === 'agregar') {
  const [fecha, descripcion, monto, categoria = 'Otros'] = args
  const mov = { fecha, descripcion, monto: Number(monto), categoria: categoria as Categoria }
  const errores = validarMovimiento(mov)
  if (errores.length > 0) {
    console.error(errores.join('\n'))
    process.exit(1)
  }
  guardar(RUTA, [...leer(RUTA), mov])
  console.log('Movimiento agregado.')
} else if (comando === 'listar') {
  const movs = args[0] ? delMes(leer(RUTA), args[0]) : leer(RUTA)
  for (const m of movs) console.log(`${m.fecha}  ${m.categoria.padEnd(10)}  ${m.monto.toFixed(2).padStart(10)}  ${m.descripcion}`)
} else {
  console.log('Uso: finanzas agregar <AAAA-MM-DD> <descripción> <monto> [categoría]\n     finanzas listar [AAAA-MM]')
}
